content.text:
{
  "name": "PI E-816压电定位控制器",
  "name_en": "PI E-816 Piezo Positioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于驱动压电定位平台或压电执行器的精密运动控制器。该设备通过串口进行位置查询与运动控制，支持单通道或XY通道的位置读取、绝对/相对移动、到位状态检查、漂移补偿、行程范围查询和固件版本读取，常用于显微镜纳米定位、对焦或样品精密扫描。",
  "description_en": "A precision motion controller for driving a piezo positioning stage or piezo actuator. It communicates over a serial interface and supports position readback, absolute and relative moves, XY motion, on-target status checks, drift compensation, travel range queries, and firmware version retrieval. It is commonly used for microscope nanopositioning, focus control, and fine sample scanning.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与压电控制器的连接。",
      "description_en": "Close the connection to the piezo controller."
    },
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化压电控制器连接。",
      "description_en": "Reinitialize the piezo controller connection."
    },
    {
      "action_name": "auto-OnTarget",
      "description": "查询设备是否已到达目标位置。",
      "description_en": "Query whether the device has reached its target position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定通道的当前位置。",
      "description_en": "Get the current position of the specified channel."
    },
    {
      "action_name": "auto-GetPosXY",
      "description": "获取XY通道的当前位置。",
      "description_en": "Get the current positions of the X and Y channels."
    },
    {
      "action_name": "auto-GetTargetPos",
      "description": "获取指定通道的目标位置。",
      "description_en": "Get the target position of the specified channel."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到绝对目标位置，可设置速度。",
      "description_en": "Move the specified channel to an absolute target position, optionally with a set velocity."
    },
    {
      "action_name": "auto-MoveRel",
      "description": "使指定通道相对当前位置移动指定增量。",
      "description_en": "Move the specified channel by a relative increment from its current position."
    },
    {
      "action_name": "auto-MoveInDir",
      "description": "按给定的dx和dy执行XY方向移动。",
      "description_en": "Perform XY motion using the given dx and dy values."
    },
    {
      "action_name": "auto-SetDriftCompensation",
      "description": "启用或禁用漂移补偿。",
      "description_en": "Enable or disable drift compensation."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否处于就绪状态。",
      "description_en": "Query whether the controller is in a ready state."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取通道对象。",
      "description_en": "Get the channel object."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取通道相位信息。",
      "description_en": "Get channel phase information."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置限制。",
      "description_en": "Get the minimum position limit of the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置限制。",
      "description_en": "Get the maximum position limit of the specified channel."
    },
    {
      "action_name": "auto-GetFirmwareVersion",
      "description": "获取控制器固件版本。",
      "description_en": "Get the controller firmware version."
    }
  ],
  "tag_hints": [
    "piezo nanopositioning",
    "microscope focus control",
    "XY stage motion",
    "serial motion controller",
    "drift compensation",
    "on-target status",
    "travel range limits",
    "firmware query"
  ]
}

